def section_bounds(lines):
    heads = [(i, l) for i, l in enumerate(lines) if l.startswith('## ')]
    return heads
heads = section_bounds(lines)
def end_of(section_prefix):
    for k, (i, l) in enumerate(heads):
        if l.startswith(f'## {section_prefix}.'):
            nxt = heads[k + 1][0] if k + 1 < len(heads) else len(lines)
            j = nxt
            while j > i and lines[j - 1].strip() == '': j -= 1
            return j
    raise KeyError(section_prefix)
