def fmt(v):
    if v is None or (isinstance(v, float) and pd.isna(v)) or v == '': return '—'
    if isinstance(v, (bool,)) or str(v) in ('True', 'False'): return str(v)
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if v == int(v) and abs(v) < 1e15: return str(int(v))
        if abs(v) < 1e-4 and v != 0: return f'{v:.4e}'
        return str(Decimal(repr(v)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP))
    s = str(v)
    return s.replace('|', '\\|')
def md_table(df, cols, rename=None):
    rename = rename or {}
    head = [rename.get(c, c.replace('_', ' ')) for c in cols]
    out = ['| CSV row | ' + ' | '.join(head) + ' |', '| --- |' + ' --- |' * len(cols)]
    for i, (_, r) in enumerate(df.iterrows(), 1):
        out.append(f'| {i} | ' + ' | '.join(fmt(r[c]) for c in cols) + ' |')
    return out
def panel(title, note, df, cols, rename=None):
    return ['<div class="table-panel" markdown="1">', '', f'#### {title}', '', note, ''] + md_table(df, cols, rename) + ['', '</div>', '']
def prov(path):
    rel = str(Path(path).resolve().relative_to(ROOT))
    return f'Source CSV: `{rel}`; SHA-256 `{sha(path)}`.'
